//! Shared borrowed header projection for native session adapters.
use codetether_session_codec::HeaderView;
/// Session fields available to the compact header codec.
/// # Implementors
/// Generated by [crate::impl_session_store!] for the application's local session.
pub trait HeaderSource {
    /// Borrow the existing scalar and metadata fields without cloning.
    fn header(&self) -> HeaderView<'_>;
}
/// Borrow session fields for live or legacy header encoding.
/// # Arguments
/// * `session` - Session whose existing fields should be projected.
/// # Returns
/// A borrowed view with the existing identity, timestamps, metadata and usage.
/// # Examples
/// ```no_run
/// # fn example(session: &impl codetether_session_schema::HeaderSource) {
/// let view = codetether_session_schema::header(session);
/// assert_eq!(view.id, session.header().id);
/// # }
/// ```
pub fn header(session: &impl HeaderSource) -> HeaderView<'_> {
    session.header()
}
